<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $healthStatuses = \SimpleCdn\Cdn::getHealthStatus(); $nodesFile = __DIR__ . '/../nodes.json'; $nodes = []; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $nodes = $decoded; } } } $message = ''; $messageType = 'info'; if ($_SERVER['REQUEST_METHOD'] === 'POST') { $action = $_POST['action'] ?? ''; if ($action === 'add_node') { $newNode = [ 'id' => trim($_POST['node_id'] ?? ''), 'name' => trim($_POST['node_name'] ?? ''), 'domain' => trim($_POST['node_domain'] ?? ''), 'origin' => trim($_POST['node_origin'] ?? ''), 'regions' => $_POST['node_regions'] ?? [], 'weight' => (int) ($_POST['node_weight'] ?? 100), 'enabled' => isset($_POST['node_enabled']) && $_POST['node_enabled'] === '1', ]; if ($newNode['id'] === '' || $newNode['domain'] === '' || $newNode['origin'] === '') { $message = '节点ID、域名、回源站点均为必填项'; $messageType = 'error'; } elseif (isset($_POST['edit_index']) && is_numeric($_POST['edit_index'])) { $index = (int) $_POST['edit_index']; if (isset($nodes[$index])) { $nodes[$index] = $newNode; $message = '节点已更新'; } } else { $dup = false; foreach ($nodes as $n) { if ($n['id'] === $newNode['id']) { $dup = true; break; } } if ($dup) { $message = '节点ID已存在'; $messageType = 'error'; } else { $nodes[] = $newNode; $message = '节点已添加'; } } if ($messageType !== 'error') { $json = json_encode($nodes, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT); if (@file_put_contents($nodesFile, $json) !== false) { if ($message === '') { $message = '操作成功'; } } else { $message = '保存失败，请检查 nodes.json 目录写权限'; $messageType = 'error'; } } if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $nodes = $decoded; } } } } if ($action === 'delete_node') { $index = (int) ($_POST['node_index'] ?? -1); if (isset($nodes[$index])) { array_splice($nodes, $index, 1); $json = json_encode($nodes, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT); if (@file_put_contents($nodesFile, $json) !== false) { $message = '节点已删除'; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $nodes = $decoded; } } } } else { $message = '删除失败，请检查写权限'; $messageType = 'error'; } } else { $message = '节点不存在'; $messageType = 'error'; } } if ($action === 'toggle_node') { $index = (int) ($_POST['node_index'] ?? -1); $enable = $_POST['enable'] === '1'; if (isset($nodes[$index])) { $nodes[$index]['enabled'] = $enable; $json = json_encode($nodes, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT); if (@file_put_contents($nodesFile, $json) !== false) { $message = $enable ? '节点已启用' : '节点已禁用'; if (is_file($nodesFile)) { $content = @file_get_contents($nodesFile); if ($content !== false) { $decoded = @json_decode($content, true); if (is_array($decoded)) { $nodes = $decoded; } } } } else { $message = '操作失败，请检查写权限'; $messageType = 'error'; } } else { $message = '节点不存在'; $messageType = 'error'; } } } $editNode = null; $editIndex = -1; if (isset($_GET['edit']) && is_numeric($_GET['edit'])) { $idx = (int) $_GET['edit']; if (isset($nodes[$idx])) { $editNode = $nodes[$idx]; $editIndex = $idx; } } $regionOptions = [ 'CN' => '中国', 'CN-BJ' => '中国-北京', 'CN-SH' => '中国-上海', 'CN-GD' => '中国-广东', 'SG' => '新加坡', 'MY' => '马来西亚', 'TH' => '泰国', 'VN' => '越南', 'ID' => '印度尼西亚', 'PH' => '菲律宾', 'US' => '美国', 'CA' => '加拿大', 'MX' => '墨西哥', 'JP' => '日本', 'KR' => '韩国', 'HK' => '中国香港', 'TW' => '中国台湾', '*' => '全部地区（兜底）', ]; function escVal($val): string { return htmlspecialchars((string) $val, ENT_QUOTES, 'UTF-8'); } function isRegionSelected(string $code, ?array $regions): bool { if ($regions === null) { return false; } return in_array($code, $regions, true); } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 多节点管理</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1100px; margin: 24px auto; padding: 0 20px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .card h2 { font-size: 18px; margin: 0 0 16px; color: #0f172a; } .msg { padding: 10px 16px; border-radius: 6px; margin-bottom: 16px; font-size: 14px; } .msg.info { background: #dbeafe; color: #1e40af; border: 1px solid #bfdbfe; } .msg.error { background: #fee2e2; color: #991b1b; border: 1px solid #fecaca; } .msg.success { background: #dcfce7; color: #166534; border: 1px solid #86efac; } .table { width: 100%; border-collapse: collapse; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .btn { display: inline-block; padding: 6px 12px; background: #2563eb; color: #fff; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-danger { background: #dc2626; } .btn-danger:hover { background: #b91c1c; } .btn-sm { padding: 4px 8px; font-size: 12px; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-enabled { background: #dcfce7; color: #166534; } .badge-disabled { background: #f1f5f9; color: #64748b; } .badge-online { background: #dcfce7; color: #166534; } .badge-offline { background: #fee2e2; color: #991b1b; } .badge-unknown { background: #f1f5f9; color: #94a3b8; } .region-tag { display: inline-block; padding: 2px 6px; background: #e2e8f0; color: #475569; border-radius: 4px; font-size: 11px; margin: 1px; } .form-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; margin-bottom: 12px; } .form-group { display: flex; flex-direction: column; } .form-group label { font-size: 13px; color: #64748b; margin-bottom: 4px; } .form-group input, .form-group select, .form-group textarea { padding: 8px; border: 1px solid #e2e8f0; border-radius: 6px; font-size: 13px; font-family: inherit; } .form-group textarea { resize: vertical; min-height: 60px; } .form-group.full { grid-column: 1 / -1; } .checkbox-group { display: flex; align-items: center; gap: 8px; margin-top: 22px; } .checkbox-group input { width: 18px; height: 18px; } .regions-select { grid-column: 1 / -1; } .regions-select select { height: 100px; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } </style> </head> <body> <div class="topbar"> <h1>多节点管理</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> <?php if ($message): ?> <div class="msg <?php echo $messageType === 'error' ? 'error' : 'success'; ?>"><?php echo escVal($message); ?></div> <?php endif; ?> <div class="card"> <h2><?php echo $editNode !== null ? '编辑节点' : '添加节点'; ?></h2> <form method="POST" action=""> <?php if ($editNode !== null): ?> <input type="hidden" name="action" value="add_node"> <input type="hidden" name="edit_index" value="<?php echo $editIndex; ?>"> <?php else: ?> <input type="hidden" name="action" value="add_node"> <?php endif; ?> <div class="form-row"> <div class="form-group"> <label>节点 ID</label> <input type="text" name="node_id" value="<?php echo escVal($editNode !== null ? ($editNode['id'] ?? '') : ''); ?>" placeholder="如 node-bj" required> </div> <div class="form-group"> <label>节点名称</label> <input type="text" name="node_name" value="<?php echo escVal($editNode !== null ? ($editNode['name'] ?? '') : ''); ?>" placeholder="如 北京节点" required> </div> <div class="form-group"> <label>节点域名</label> <input type="url" name="node_domain" value="<?php echo escVal($editNode !== null ? ($editNode['domain'] ?? '') : ''); ?>" placeholder="如 https://bj.cdn.example.com" required> <div class="muted">访问者将被 302 重定向到此域名</div> </div> <div class="form-group"> <label>回源站点</label> <input type="url" name="node_origin" value="<?php echo escVal($editNode !== null ? ($editNode['origin'] ?? '') : ''); ?>" placeholder="如 https://origin.example.com" required> <div class="muted">未命中缓存时回源抓取此站点</div> </div> </div> <div class="form-group regions-select"> <label>覆盖地区（按住 Ctrl 可多选）</label> <select name="node_regions[]" multiple class="regions-select" <?php echo $editNode !== null ? '' : 'required'; ?>> <?php foreach ($regionOptions as $code => $label): ?> <?php $selected = isRegionSelected($code, $editNode !== null ? ($editNode['regions'] ?? null) : null); ?> <option value="<?php echo escVal($code); ?>" <?php echo $selected ? 'selected' : ''; ?>><?php echo escVal($label); ?></option> <?php endforeach; ?> </select> </div> <div class="form-row"> <div class="form-group"> <label>权重（数字越大优先级越高）</label> <input type="number" name="node_weight" value="<?php echo escVal($editNode !== null ? ($editNode['weight'] ?? 100) : 100); ?>" min="1" max="1000"> </div> <div class="form-group"> <label style="margin-bottom: 4px;">&nbsp;</label> <div class="checkbox-group"> <input type="checkbox" name="node_enabled" value="1" <?php echo (($editNode !== null ? ($editNode['enabled'] ?? true) : true) ? 'checked' : ''); ?> id="node_enabled"> <label for="node_enabled" style="margin:0;">启用该节点</label> </div> </div> </div> <div style="display:flex;gap:12px;"> <button type="submit" class="btn"><?php echo $editNode !== null ? '更新节点' : '添加节点'; ?></button> <?php if ($editNode !== null): ?> <a href="nodes.php" class="btn-secondary">取消</a> <?php endif; ?> </div> </form> </div> <div class="card"> <h2>节点列表（共 <?php echo count($nodes); ?> 个）</h2> <?php if (empty($nodes)): ?> <p class="empty">暂无节点配置，请先添加一个节点。</p> <?php else: ?> <table class="table"> <thead> <tr> <th style="width:12%;">ID</th> <th style="width:16%;">名称</th> <th style="width:20%;">域名</th> <th style="width:16%;">回源站点</th> <th style="width:12%;">覆盖地区</th> <th style="width:7%;">权重</th> <th style="width:10%;">健康</th> <th style="width:10%;">状态</th> <th style="width:auto;">操作</th> </tr> </thead> <tbody> <?php foreach ($nodes as $i => $node): ?> <tr> <td><?php echo escVal($node['id'] ?? ''); ?></td> <td><?php echo escVal($node['name'] ?? ''); ?></td> <td><?php echo escVal($node['domain'] ?? ''); ?></td> <td><?php echo escVal($node['origin'] ?? ''); ?></td> <td> <?php $regions = $node['regions'] ?? []; if (empty($regions)) { echo '<span class="muted">未设置</span>'; } else { foreach ($regions as $r) { $label = $regionOptions[$r] ?? $r; echo '<span class="region-tag">' . escVal($label) . '</span>'; } } ?> </td> <td><?php echo (int) ($node['weight'] ?? 0); ?></td> <td> <?php $nodeId = $node['id'] ?? ''; $health = $healthStatuses[$nodeId] ?? null; if ($health === null) { echo '<span class="badge badge-unknown">未检测</span>'; } elseif ($health['status'] === 'online') { echo '<span class="badge badge-enabled">在线</span>'; if ($health['response_time'] !== false) { echo '<br><span class="muted" style="font-size:11px;">' . $health['response_time'] . 'ms</span>'; } } else { echo '<span class="badge badge-disabled">离线</span>'; if (!empty($health['error'])) { echo '<br><span class="muted" style="font-size:11px;">' . escVal($health['error']) . '</span>'; } } ?> </td> <td> <span class="badge <?php echo (isset($node['enabled']) && $node['enabled'] === true) ? 'badge-enabled' : 'badge-disabled'; ?>"> <?php echo (isset($node['enabled']) && $node['enabled'] === true) ? '启用' : '禁用'; ?> </span> </td> <td> <a href="action.php?do=toggle_node&index=<?php echo $i; ?>&enable=<?php echo (isset($node['enabled']) && $node['enabled'] === true) ? '0' : '1'; ?>" class="btn btn-sm btn-secondary" onclick="return confirm('确定<?php echo (isset($node['enabled']) && $node['enabled'] === true) ? '禁用' : '启用'; ?>此节点吗？');"> <?php echo (isset($node['enabled']) && $node['enabled'] === true) ? '禁用' : '启用'; ?> </a> <a href="nodes.php?edit=<?php echo $i; ?>" class="btn btn-sm btn-secondary">编辑</a> <a href="action.php?do=delete_node&index=<?php echo $i; ?>" class="btn btn-sm btn-danger" onclick="return confirm('确定删除此节点吗？');">删除</a> </td> </tr> <?php endforeach; ?> </tbody> </table> <?php endif; ?> </div> <div class="card"> <h2>配置说明</h2> <div class="muted"> <ul style="margin:0; padding-left:20px;"> <li>节点数据保存在 <code>nodes.json</code> 文件中，请确保该目录对 Web 用户可写。</li> <li><strong>调度逻辑</strong>：访问者访问主站时，系统会根据 IP 判断地区，302 重定向到匹配的 CDN 节点。</li> <li><strong>地区匹配顺序</strong>：精确地区（如 CN-BJ）&gt; 国家级（如 CN）&gt; 兜底节点（如 * 或 --）。</li> <li><strong>权重</strong>：同地区多个节点时，权重越高越优先被选中。</li> <li>修改节点后立即生效，无需重启 Web 服务器。</li> </ul> </div> </div> </div> </body> </html>;